/**
 * 从一棵子树删除一项的内部方法.
 * 参数 x 是要被删除的项.
 * 参数 t 为该子树的根节点.
 * 置该子树的新的根.
 */
void remove( const Comparable & x, BinaryNode * & t )
{
    if( t == nullptr )
        return;   // 项没找到; 什么也不做
    if( x < t->element )
        remove( x, t->left );
    else if( t->element < x )
        remove( x, t->right );
    else if( t->left != nullptr && t->right != nullptr ) // 有两个儿子
    {
        t->element = findMin( t->right )->element;
        remove( t->element, t->right );
    }
    else
    {
        BinaryNode *oldNode = t;
        t = ( t->left != nullptr ) ? t->left : t->right;
        delete oldNode;
    }
}

/**
 * 二叉查找树的析构函数
 */
~BinarySearchTree( )
{
    makeEmpty( );
}
/**
 * 使子树为空的内部方法.
 */
void makeEmpty( BinaryNode * & t )
{
    if( t != nullptr )
    {
        makeEmpty( t->left );
        makeEmpty( t->right );
        delete t;
    }
    t = nullptr;
}

/**
 * 拷贝构造函数
 */
BinarySearchTree( const BinarySearchTree & rhs ) : root{ nullptr }
{
    root = clone( rhs.root );
}

/**
 * 克隆子树的内部方法.
 */
BinaryNode * clone( BinaryNode *t ) const
{
    if( t == nullptr )
        return nullptr;
    else
        return new BinaryNode{ t->element, clone( t->left ), clone( t->right ) };
}

struct AvlNode
{
    Comparable element;
    AvlNode *left;
    AvlNode *right;
    int height;

    AvlNode( const Comparable & ele, AvlNode *lt, AvlNode *rt, int h = 0 )
    : element{ ele }, left{ lt }, right{ rt }, height{ h } { }

    AvlNode( Comparable && ele, AvlNode *lt, AvlNode *rt, int h = 0 )
    : element{ std::move( ele ) }, left{ lt }, right{ rt }, height{ h } { }
};

/**
 * 返回节点t的高度，如果是nullptr则返回-1.
 */
int height( AvlNode *t ) const
{
    return t == nullptr ? -1 : t->height;
}

/**
 * 向一棵子树进行插入的内部方法.
 * x 是要插入的项.
 * t 为该子树的根节点.
 * 设置子树的新根.
 */
void insert( const Comparable & x, AvlNode * & t )
{
    if( t == nullptr )
        t = new AvlNode{ x, nullptr, nullptr };
    else if( x < t->element )
        insert( x, t->left );
    else if( t->element < x )
        insert( x, t->right );

    balance( t );
}

static const int ALLOWED_IMBALANCE = 1;

// 假设t是平衡的，或与平衡相差不超过1
void balance( AvlNode * & t )
{
    if( t == nullptr )
        return;

if( height( t->left ) - height( t->right ) > ALLOWED_IMBALANCE )
    if( height( t->left->left ) >= height( t->left->right ) )
        rotateWithLeftChild( t );
    else
        doubleWithLeftChild( t );
else
if( height( t->right ) - height( t->left ) > ALLOWED_IMBALANCE )
    if( height( t->right->right ) >= height( t->right->left ) )
        rotateWithRightChild( t );
    else
        doubleWithRightChild( t );

t->height = max( height( t->left ), height( t->right ) ) + 1;
}

/**
 * 用左儿子旋转二叉树的节点.
 * 这是对 AVL 树在情形1的一次单旋转.
 * 更新高度，然后设置新根.
 */
void rotateWithLeftChild( AvlNode * & k2 )
{
    AvlNode *k1 = k2->left;
    k2->left = k1->right;
    k1->right = k2;
    k2->height = max( height( k2->left ), height( k2->right ) ) + 1;
    k1->height = max( height( k1->left ), k2->height ) + 1;
    k2 = k1;
}

/**
 * 双旋转二叉树的节点: 首先左儿子和它的右儿子进行.
 * 然后节点k3和新的左儿子进行.
 * 这是对AVL树情形2的一次双旋转.
 * 更新高度, 然后设置新根.
 */
void doubleWithLeftChild( AvlNode * & k3 )
{
    rotateRightChild( k3->left );
    rotateLeftChild( k3 );
}

/**
 * 从子树实施删除的内部方法.
 * x 是要被删除的项.
 * t 为该子树的根节点.
 * 设置该子树的新根.
 */
void remove( const Comparable & x, AvlNode * & t )
{
    if( t == nullptr )
        return;  // 没发现要删除的项；什么也不做

    if( x < t->element )
        remove( x, t->left );
    else if( t->element < x )
        remove( x, t->right );
    else if( t->left != nullptr && t->right != nullptr ) // 两个儿子
    {
        t->element = findMin( t->right )->element;
        remove( t->element, t->right );
    }
    else
    {
        AvlNode *oldNode = t;
        t = ( t->left != nullptr ) ? t->left : t->right;
        delete oldNode;
    }

    balance( t );
}

/**
 * 按排序顺序打印树的内容.
 */
void printTree( ostream & out = cout ) const
{
    if( isEmpty( ) )
        out << "Empty tree" << endl;
    else
        printTree( root, out );
}

/**
 * 以排序顺序打印根在 t 处的子树的内部方法.
 */
void printTree( BinaryNode *t, ostream & out ) const
{
    if( t != nullptr )
    {
        printTree( t->left, out );
        out << t->element << endl;
        printTree( t->right, out );
    }
}

/**
 * 计算根在t处子树的高度的内部方法.
 */
int height( BinaryNode *t )
{
    if( t == nullptr )
        return -1;
    else
        return 1 + max( height( t->left ), height( t->right ) );
}

