// 如果word1和word2具有相同的长度
// 并且只有一个字母不同，则返回true
bool oneCharOff( const string & word1, const string & word2 )
{
    if( word1.length( ) != word2.length( ))
        return false;

    int diffs = 0;

    for( int i = 0; i < word1.length( ); ++i )
        if( word1[ i ] != word2[ i ] )
            if( ++diffs > 1 )
                return false;

    return diffs == 1;
}

